namespace devbench::json {

enum class ErrorCode : uint32_t {
    Ok = 0,
    InvalidJson,
    UnexpectedToken,
    UnexpectedEndOfInput,
    UnterminatedString,
    InvalidNumber,
    InvalidEscapeSequence,
    InvalidUnicode,
    DepthLimitExceeded,
    AllocationFailure
};

struct ParseError {
    ErrorCode code;
    size_t offset;
    size_t line;
    size_t column;
    const char* message;
};

class ArenaAllocator {
public:
    explicit ArenaAllocator(size_t chunk_size = 65536);
    ~ArenaAllocator();

    ArenaAllocator(const ArenaAllocator&) = delete;
    ArenaAllocator& operator=(const ArenaAllocator&) = delete;
    ArenaAllocator(ArenaAllocator&&) noexcept;
    ArenaAllocator& operator=(ArenaAllocator&&) noexcept;

    void* allocate(size_t size, size_t alignment = alignof(std::max_align_t));
    template <typename T, typename... Args>
    T* create(Args&&... args);

    void reset() noexcept;
    size_t total_allocated() const noexcept;
    size_t total_capacity() const noexcept;

private:
    struct Chunk;
    Chunk* current_chunk_{nullptr};
    Chunk* head_chunk_{nullptr};
    size_t chunk_size_{65536};
};

enum class Type : uint8_t {
    Null = 0,
    Boolean,
    Int64,
    Uint64,
    Double,
    String,
    Array,
    Object
};

class Value;

struct Member {
    std::string_view key;
    Value* value;
};

class Array {
public:
    using iterator = Value*;
    using const_iterator = const Value*;

    explicit Array(ArenaAllocator& arena);
    void push_back(Value val);
    size_t size() const noexcept;
    bool empty() const noexcept;
    Value& operator[](size_t idx);
    const Value& operator[](size_t idx) const;

    iterator begin() noexcept;
    iterator end() noexcept;
    const_iterator begin() const noexcept;
    const_iterator end() const noexcept;

private:
    Value* data_{nullptr};
    size_t size_{0};
    size_t capacity_{0};
    ArenaAllocator* arena_{nullptr};
};

class Object {
public:
    using iterator = Member*;
    using const_iterator = const Member*;

    explicit Object(ArenaAllocator& arena);
    void insert(std::string_view key, Value val);
    Value* find(std::string_view key) noexcept;
    const Value* find(std::string_view key) const noexcept;
    size_t size() const noexcept;
    bool empty() const noexcept;

    iterator begin() noexcept;
    iterator end() noexcept;
    const_iterator begin() const noexcept;
    const_iterator end() const noexcept;

private:
    Member* members_{nullptr};
    size_t size_{0};
    size_t capacity_{0};
    ArenaAllocator* arena_{nullptr};
};

class Value {
public:
    Value() noexcept : type_(Type::Null), raw_int_(0) {}
    Value(std::nullptr_t) noexcept : type_(Type::Null), raw_int_(0) {}
    Value(bool b) noexcept : type_(Type::Boolean), bool_val_(b) {}
    Value(int64_t i) noexcept : type_(Type::Int64), int_val_(i) {}
    Value(uint64_t u) noexcept : type_(Type::Uint64), uint_val_(u) {}
    Value(double d) noexcept : type_(Type::Double), double_val_(d) {}
    Value(std::string_view s) noexcept : type_(Type::String), string_val_(s) {}
    Value(Array* a) noexcept : type_(Type::Array), array_val_(a) {}
    Value(Object* o) noexcept : type_(Type::Object), object_val_(o) {}

    Type type() const noexcept { return type_; }
    bool is_null() const noexcept { return type_ == Type::Null; }
    bool is_bool() const noexcept { return type_ == Type::Boolean; }
    bool is_int() const noexcept { return type_ == Type::Int64; }
    bool is_uint() const noexcept { return type_ == Type::Uint64; }
    bool is_double() const noexcept { return type_ == Type::Double; }
    bool is_string() const noexcept { return type_ == Type::String; }
    bool is_array() const noexcept { return type_ == Type::Array; }
    bool is_object() const noexcept { return type_ == Type::Object; }

    bool as_bool() const { return bool_val_; }
    int64_t as_int() const { return int_val_; }
    uint64_t as_uint() const { return uint_val_; }
    double as_double() const { return double_val_; }
    std::string_view as_string() const { return string_val_; }
    Array& as_array() { return *array_val_; }
    const Array& as_array() const { return *array_val_; }
    Object& as_object() { return *object_val_; }
    const Object& as_object() const { return *object_val_; }

private:
    Type type_{Type::Null};
    union {
        bool bool_val_;
        int64_t int_val_;
        uint64_t uint_val_;
        double double_val_;
        std::string_view string_val_;
        Array* array_val_;
        Object* object_val_;
        uint64_t raw_int_;
    };
};

class Document {
public:
    Document();
    explicit Document(size_t arena_chunk_size);
    ~Document() = default;

    ParseError parse(std::string_view json);
    ParseError parse_inplace(char* json, size_t length);

    Value& root() noexcept { return root_; }
    const Value& root() const noexcept { return root_; }
    ArenaAllocator& arena() noexcept { return arena_; }

    std::string serialize(bool pretty = false) const;
    void serialize_to(std::string& out, bool pretty = false) const;

private:
    ArenaAllocator arena_;
    Value root_{};
};

class Serializer {
public:
    static void serialize(const Value& val, std::string& buffer, bool pretty = false, size_t indent = 0);
};

} // namespace devbench::json

#endif // DEVBENCH_JSON_PARSER_HPP
```

---

## 5. Parser & Lexer Implementation Architecture

### 5.1 Lexer & Parsing Strategy
1. **Whitespace Skipping**: Branchless lookup table or vectorized scanning for `' '`, `\t`, `\n`, `\r`.
2. **Number Parsing**: Fast string-to-float / integer parsing utilizing optimized base-10 accumulation and standard IEEE 754 float conversion (`std::from_chars`).
3. **Zero-Copy Strings**: Validates UTF-8 and JSON escape sequences. For unescaped strings, slices `std::string_view` directly from input. For escaped strings, resolves in-place (in `parse_inplace`) or copies escaped translations to arena.
4. **Recursive Descent with Stack Depth Control**: Enforces a max depth limit (e.g. 1024 levels) to defend against recursive stack exhaustion attacks.

---

## 6. Serializer Architecture
- **Buffer Pre-Allocation**: Heuristic capacity reservation minimizes reallocation during serialization.
- **Fast Formatting**: Integer and floating-point conversion via `std::to_chars` (locale-independent, zero heap allocation).
- **Format Modes**: Supports both ultra-compact serialization (zero whitespace) and formatted pretty-printing with configurable indentation.

---

