            assertThrows(TokenExpiredException.class, () -> authService.refreshToken(expiredRefreshToken));
            verify(userRepository, never()).findByUsername(anyString());
        }

        @Test
        @DisplayName("Should throw BadCredentialsException when refresh token is invalid or malformed")
        void refreshToken_InvalidToken_ThrowsException() {
            String invalidToken = "malformed.jwt.token";
            given(jwtTokenProvider.validateToken(invalidToken)).willReturn(false);

            assertThrows(BadCredentialsException.class, () -> authService.refreshToken(invalidToken));
            verify(jwtTokenProvider, never()).getUsernameFromToken(anyString());
        }

        @Test
        @DisplayName("Should validate token expiration boundary accurately")
        void validateTokenExpiration_BoundaryCheck() {
            String validToken = "boundary.test.token";
            Date futureExpiration = new Date(System.currentTimeMillis() + 3600000);
            Date pastExpiration = new Date(System.currentTimeMillis() - 1000);

            given(jwtTokenProvider.getExpirationDateFromToken(validToken)).willReturn(futureExpiration);
            assertFalse(jwtTokenProvider.getExpirationDateFromToken(validToken).before(new Date()));

            given(jwtTokenProvider.getExpirationDateFromToken("expired.token")).willReturn(pastExpiration);
            assertTrue(jwtTokenProvider.getExpirationDateFromToken("expired.token").before(new Date()));
        }
    }
}

# Software Design Document: Analytics Dashboard Frontend (devbench-react-dashboard)

## 1. Executive Summary & Architectural Overview
The `devbench-react-dashboard` is a real-time analytics dashboard built using React 19, Tailwind CSS, and a resilient WebSocket client. It monitors system performance telemetry (CPU, Memory, Network I/O, Request Latency, Throughput, and Error Rates) streamed with low latency.

### System Architecture Diagram
```
+-------------------------------------------------------------------------+
|                              Browser / React 19                         |
|                                                                         |
|  +-------------------------------------------------------------------+  |
|  |                    Telemetry Context / State Hook                 |  |
|  |   - Metric Ring Buffers (Time-Series)  - Connection State         |  |
|  |   - Active Subscriptions Map           - Aggregated Health Status |  |
|  +-------------------------------------------------------------------+  |
|            ^                                     |                      |
|            | Dispatches telemetry frames         | State updates        |
|  +---------------------------+         +-----------------------------+  |
|  | WebSocket Telemetry Client|         |   Component Tree            |  |
|  | - Exponential Backoff     |         |   - Dashboard (Root)        |  |
|  | - Heartbeat / Ping-Pong   |         |   - MetricCard / MetricGrid |  |
|  | - Frame Validation/Parse  |         |   - TimeSeriesChart         |  |
|  +---------------------------+         |   - SubscriptionBar         |  |
|            ^                           +-----------------------------+  |
+------------|------------------------------------------------------------+
             | WS Binary / JSON Framing
             v
+-------------------------------------------------------------------------+
|                  Backend Telemetry & Streaming Server                   |
+-------------------------------------------------------------------------+
```

---

## 2. State Management Architecture

### 2.1 State Model & Slices
1. **Connection State**: Tracks WebSocket connectivity (`CONNECTING`, `OPEN`, `CLOSING`, `CLOSED`, `RECONNECTING`), latency ping (RTT), and reconnect attempt counter.
2. **Telemetry Cache (Buffer Windowing)**:
   - Maintains fixed-capacity ring buffers per metric identifier (e.g., last 60-300 data points for 1s-5s sampling intervals) to prevent unbounded memory growth.
   - Computes real-time statistics (min, max, mean, p95, p99, trend slope).
3. **Subscriptions State**: Set of subscribed topic IDs and sampling rates (`frequencyMs`, `compression`, `filterTags`).
4. **Alerts & System Health**: Aggregates threshold breaches, warning levels, and critical incidents into an active alerts queue.

### 2.2 Reducer / State Transition Flow
```typescript
type TelemetryAction =
  | { type: 'WS_STATUS_CHANGED'; payload: { status: ConnectionStatus; error?: string } }
  | { type: 'METRICS_BATCH_RECEIVED'; payload: { points: MetricTelemetryPoint[] } }
  | { type: 'SUBSCRIBE_TOPIC'; payload: { topic: string; options?: SubscriptionOptions } }
  | { type: 'UNSUBSCRIBE_TOPIC'; payload: { topic: string } }
  | { type: 'CLEAR_ALERTS' }
  | { type: 'SET_RETENTION_WINDOW'; payload: { windowSeconds: number } };
```

---

## 3. WebSocket Subscription Protocol

### 3.1 Protocol Specification & Message Format
Communication is bi-directional over WebSocket JSON protocol with standard framing.

#### Client-to-Server Messages:
1. **Subscribe**:
   ```json
   {
     "action": "SUBSCRIBE",
     "requestId": "req-123456",
     "topic": "metrics:system:cpu",
     "params": { "intervalMs": 1000, "aggregate": "avg" }
   }
   ```
2. **Unsubscribe**:
   ```json
   {
     "action": "UNSUBSCRIBE",
     "requestId": "req-123457",
     "topic": "metrics:system:cpu"
   }
   ```
3. **Heartbeat / Ping**:
   ```json
   { "action": "PING", "timestamp": 1717000000000 }
   ```

#### Server-to-Client Messages:
1. **Telemetry Feed Data**:
   ```json
   {
     "type": "TELEMETRY",
     "topic": "metrics:system:cpu",
     "timestamp": 1717000000500,
     "data": {
       "metricId": "cpu_usage",
       "value": 42.8,
       "unit": "%",
       "tags": { "host": "prod-api-01", "core": "all" }
     }
   }
   ```
2. **Subscription Acknowledgment (ACK / NACK)**:
   ```json
   {
     "type": "ACK",
     "requestId": "req-123456",
     "status": "SUCCESS",
     "topic": "metrics:system:cpu"
   }
   ```
3. **Pong**:
   ```json
   { "type": "PONG", "timestamp": 1717000000000, "serverTime": 1717000000005 }
   ```

### 3.2 Connection Lifecycle & Resilience
- **Auto-reconnect**: Exponential backoff with jitter (`initialDelay = 1000ms`, `factor = 1.5`, `maxDelay = 30000ms`, `maxRetries = 10`).
- **Resubscription**: On reconnect, automatically re-issues subscriptions for all active topics.
- **Heartbeat Timeout**: Sends `PING` every 15s; triggers reconnect if `PONG` not received within 5s.

---

## 4. Component Tree & UI Hierarchy

```
<App>
  └── <TelemetryProvider wsUrl="...">
        └── <Dashboard>
              ├── <DashboardHeader>
              │     ├── <ConnectionBadge status={status} pingMs={pingMs} />
              │     ├── <TimeRangeSelector value={range} onChange={setRange} />
              │     └── <SubscriptionFilter topics={topics} onToggle={toggleTopic} />
              ├── <SystemHealthOverview health={systemHealth} alerts={alerts} />
              ├── <MetricGrid>
              │     ├── <MetricCard metric="cpu" data={cpuData} threshold={80} />
              │     ├── <MetricCard metric="memory" data={memData} threshold={85} />
              │     ├── <MetricCard metric="latency" data={latData} threshold={200} />
              │     └── <MetricCard metric="errors" data={errData} threshold={1} />
              ├── <TimeSeriesChartSection>
              │     ├── <TimeSeriesChart title="Compute & Memory Load" series={[cpu, mem]} />
              │     └── <TimeSeriesChart title="Throughput & Latency (P95/P99)" series={[rps, p95, p99]} />
              └── <AlertsDrawer alerts={alerts} onAcknowledge={ackAlert} />
```

---

## 5. Type Definitions & Contract Designs

### Target: `src/types/metrics.ts`
```typescript
export type MetricType = 'cpu' | 'memory' | 'network' | 'latency' | 'throughput' | 'errors';

export type HealthStatus = 'healthy' | 'degraded' | 'critical' | 'unknown';

export type ConnectionStatus = 'connecting' | 'connected' | 'disconnected' | 'reconnecting' | 'error';

export interface MetricTelemetryPoint {
  metricId: string;
  type: MetricType;
  timestamp: number;
  value: number;
  unit: string;
  tags?: Record<string, string>;
}

export interface MetricSeries {
  metricId: string;
  type: MetricType;
  name: string;
  unit: string;
  points: MetricTelemetryPoint[];
  latestValue: number;
  min: number;
  max: number;
  avg: number;
  status: HealthStatus;
}

export interface SystemHealth {
  overall: HealthStatus;
  score: number; // 0-100
  activeAlertCount: number;
  lastUpdated: number;
}

export interface TelemetryAlert {
  id: string;
  metricId: string;
  type: MetricType;
  severity: 'info' | 'warning' | 'critical';
  message: string;
  timestamp: number;
  acknowledged: boolean;
}

export interface SubscriptionConfig {
  topic: string;
  metricType: MetricType;
  intervalMs: number;
  enabled: boolean;
}

export interface WebSocketMessage<T = unknown> {
  type: 'SUBSCRIBE' | 'UNSUBSCRIBE' | 'TELEMETRY' | 'ACK' | 'PING' | 'PONG' | 'ERROR';
  requestId?: string;
  topic?: string;
  timestamp?: number;
  data?: T;
  error?: string;
}
```

